  for(let x=2;x<=10;x+=2) ctx.fillText(x,px(x),PT+PH+16);
  ctx.textAlign='right';
  for(let y=0;y<=20;y+=4) ctx.fillText(y,PL-6,py(y)+4);

  // Axis titles
  ctx.fillStyle='#666'; ctx.font='12px Georgia'; ctx.textAlign='center';
  ctx.fillText('x (horas de estudio)', PL+PW/2, H-2);
